-- V2__seed_categories_and_destinations.sql: Seed 7 Categories and 55 Verified Vizag Destinations

INSERT INTO categories (id, name, slug, description, icon) VALUES
(1, 'Beaches & Coastline', 'beaches-coastline', 'Golden sandy shores, crystal blue waters, and scenic coastal promenades along the Bay of Bengal.', 'umbrella-beach'),
(2, 'Hills & Nature', 'hills-nature', 'Lush green valleys, mist-covered mountain peaks, and enchanting hill stations of the Eastern Ghats.', 'mountain'),
(3, 'Heritage & Culture', 'heritage-culture', 'Ancient Buddhist monastic complexes, colonial architecture, and deep maritime heritage.', 'monument'),
(4, 'Museums & Monuments', 'museums-monuments', 'Historic maritime vessels, naval aviation legends, and war victory memorials.', 'landmark'),
(5, 'Spiritual & Temples', 'spiritual-temples', 'Sacred hilltop shrines, centuries-old Dravidian architecture, and harmonious pilgrimage sites.', 'place-of-worship'),
(6, 'Waterfalls & Adventure', 'waterfalls-adventure', 'Roaring forest cascades, ancient limestone caves, and trekking escapes.', 'water'),
(7, 'Parks & Wildlife', 'parks-wildlife', 'Expansive zoological reserves, coastal eco-sanctuaries, and urban botanical gardens.', 'tree');

INSERT INTO destinations (
    id, name, slug, short_description, full_description, category_id, address,
    latitude, longitude, best_time_to_visit, opening_hours, ticket_price,
    travel_tips, things_to_do, primary_image_url, featured, published
) VALUES
(1, 'Ramakrishna Beach (RK Beach)', 'ramakrishna-beach',
 'The vibrant heartbeat of Vizag coastline with scenic promenades, food stalls, and sea breeze.',
 'Ramakrishna Beach, fondly called RK Beach, is the most popular urban beachfront in Visakhapatnam. Flanked by the sweeping Beach Road, it stretches along the Bay of Bengal and is a favorite evening hangout for locals and visitors alike. The promenade is home to iconic museums, memorial statues, seaside cafés, and traditional Andhra snack stalls offering murri mixture and sweet corn.',
 1, 'Beach Road, Maharanipeta, Visakhapatnam, Andhra Pradesh 530002',
 17.7143000, 83.3236000, 'October to March', 'Open 24 hours (best 5:00 AM - 10:00 PM)', 'Free entry',
 'Swimming is strongly discouraged due to strong rip currents. Best enjoyed in early mornings for sunrise or breezy evenings.',
 'Stroll along the sea promenade, enjoy beachside street food, visit adjacent submarine museum, watch sunrise over Bay of Bengal.',
 'https://images.unsplash.com/photo-1596178065887-1198b6148b2b?auto=format&fit=crop&w=1200&q=80',
 TRUE, TRUE),

(2, 'Kailasagiri Hilltop Park', 'kailasagiri',
 'A majestic hilltop park offering 360-degree panoramic views of Vizag city and the Bay of Bengal.',
 'Perched atop a 360-foot hill overlooking the sparkling waters of the Bay of Bengal and the city grid, Kailasagiri is an iconic landmark of Visakhapatnam. The park features colossal 40-foot marble statues of Lord Shiva and Goddess Parvathi, beautifully landscaped floral gardens, a circular toy train circling the perimeter, and a scenic passenger ropeway providing thrilling aerial views.',
 2, 'Kailasagiri Hill, Visakhapatnam, Andhra Pradesh 530043',
 17.7490000, 83.3423000, 'October to March (4:00 PM to 7:30 PM)', '6:00 AM - 8:30 PM daily', 'INR 20 per person (Ropeway/Toy Train extra)',
 'Take the cable ropeway from the foothills for breathtaking coastal views. Wear comfortable walking shoes.',
 'Ride the circular mini toy train, take the cable car ropeway, photograph the Shiva-Parvathi statue, enjoy panoramic sunset viewpoints.',
 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=1200&q=80',
 TRUE, TRUE),

(3, 'Rushikonda Beach', 'rushikonda-beach',
 'The Blue Flag certified jewel of Vizag, famous for water sports, surfing, and golden sands.',
 'Rushikonda Beach is a internationally renowned Blue Flag certified beach set amidst picturesque green hills. Known as the Jewel of the East Coast, its clear turquoise waters, gentle sea gradient, and steady wind make it the hub for water sports in Andhra Pradesh, including jet skiing, speed boating, sea kayaking, and windsurfing under trained safety instructors.',
 1, 'Rushikonda, Bheemili Road, Visakhapatnam, Andhra Pradesh 530045',
 17.7825000, 83.3852000, 'October to February', '6:00 AM - 7:00 PM', 'Free entry (Water sports: INR 300 - 1500)',
 'Designated swimming zones are monitored by certified lifeguards. Always follow safety instructions for water sports.',
 'Experience jet skiing and speed boating, take surfing lessons, relax under beach shacks, swim in monitored eco-friendly zones.',
 'https://images.unsplash.com/photo-1519046904884-53103b34b206?auto=format&fit=crop&w=1200&q=80',
 TRUE, TRUE),

(4, 'Yarada Beach', 'yarada-beach',
 'A secluded tropical paradise enveloped by towering hills on three sides and deep azure sea.',
 'Nestled behind the Yarada Hills and Dolphin Nose cliff, Yarada Beach offers an unspoiled coastal retreat away from the bustle of the city. Golden sands are framed by emerald coconut plantations and steep cliff faces. The serene ambiance and crashing surf make it one of the most romantic and visually stunning shorelines in South India.',
 1, 'Yarada Village, Visakhapatnam, Andhra Pradesh 530005',
 17.6548000, 83.2704000, 'November to February', '6:00 AM - 6:00 PM', 'INR 30 village maintenance fee',
 'The surf is powerful with sudden drops; swimming deep is dangerous. Carry your own drinking water and snacks.',
 'Unwind on quiet sands, capture landscape photographs of green hills meeting the sea, enjoy fresh coconut water.',
 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?auto=format&fit=crop&w=1200&q=80',
 TRUE, TRUE),

(5, 'Sri Varaha Lakshmi Narasimha Temple (Simhachalam)', 'simhachalam-temple',
 'An ancient 11th-century hill shrine dedicated to Lord Narasimha with breathtaking Kalinga architecture.',
 'Simhachalam Temple is one of the 32 Narasimha Kshetras and a major pilgrimage center of Andhra Pradesh. Perched gracefully on the Simhachalam hill range, the temple reflects a magnificent blend of medieval Kalinga and Chola architectural styles with intricate stone carvings, an ornate 96-pillar Natya Mandapam, and spiritual chants that have resonated for a thousand years.',
 5, 'Simhachalam Hill, Visakhapatnam, Andhra Pradesh 530028',
 17.7663000, 83.2505000, 'Throughout the year', '7:00 AM - 4:00 PM & 6:00 PM - 9:00 PM', 'Free general darshan; Special darshan INR 100 - 300',
 'Traditional dress code is required (dhoti/kurta for men, saree/salwar for women). Ghat road buses operate regularly.',
 'Marvel at ornate stone carvings of the 16th century, take part in the Chandanotsavam festival, seek divine blessings.',
 'https://images.unsplash.com/photo-1582510003544-4d00b7f74220?auto=format&fit=crop&w=1200&q=80',
 TRUE, TRUE),

(6, 'INS Kursura Submarine Museum', 'ins-kursura-submarine-museum',
 'Asia’s first submarine museum preserved on a shoreline, offering a walk through naval combat history.',
 'Decommissioned in 2001 after 31 years of distinguished service including the Indo-Pakistani War of 1971, the Soviet-built Foxtrot-class submarine S20 was hauled onto the sands of RK Beach. Converted into an immersive museum, visitors can explore the narrow corridors, torpedo handling rooms, control centers, radar stations, and quarters where submariners lived beneath the waves.',
 4, 'Beach Road, Pandurangapuram, Visakhapatnam, Andhra Pradesh 530017',
 17.7172000, 83.3315000, 'October to March', '2:00 PM - 8:30 PM (Sundays: 10:00 AM - 12:30 PM, 2:00 PM - 8:30 PM; Closed Mondays)', 'INR 40 adults, INR 20 children',
 'Guided tours inside are conducted by retired naval personnel. Watch your step on high bulkhead thresholds.',
 'Walk through naval submarine control rooms, examine torpedo tubes, learn about life under the ocean during wartime.',
 'https://images.unsplash.com/photo-1544551763-46a013bb70d5?auto=format&fit=crop&w=1200&q=80',
 TRUE, TRUE),

(7, 'TU-142 Aircraft Museum', 'tu-142-aircraft-museum',
 'An imposing long-range maritime reconnaissance aircraft transformed into an interactive museum.',
 'Located right opposite the INS Kursura Submarine Museum on RK Beach, the TU-142M is a massive Soviet-era maritime reconnaissance and anti-submarine aircraft. Having served the Indian Navy with exemplary distinction for 29 accident-free years, it now houses flight deck exhibits, sonar stations, weapon bays with air-to-surface missiles, and flight simulators for aviation enthusiasts.',
 4, 'Beach Road, Opp. Submarine Museum, Visakhapatnam, Andhra Pradesh 530017',
 17.7176000, 83.3323000, 'October to March', '2:00 PM - 8:30 PM (Sundays: 10:30 AM - 8:30 PM; Closed Mondays)', 'INR 70 adults, INR 40 children',
 'Combo tickets are sometimes available with the VR flight simulator experience. Photography permits cost extra.',
 'Climb up the gangway into the pilot cockpit, inspect heavy anti-submarine torpedoes, try the virtual reality flight simulator.',
 'https://images.unsplash.com/photo-1540959733332-eab4deabeeaf?auto=format&fit=crop&w=1200&q=80',
 TRUE, TRUE),

(8, 'Sea Harrier Museum', 'sea-harrier-museum',
 'Showcase of the legendary carrier-borne jump-jet fighter that protected Indian airspace.',
 'Completing the golden naval trio on RK Beach, the Sea Harrier Museum features a suspended naval fighter jet that once took off vertically from aircraft carriers INS Vikrant and INS Viraat. Housed inside the renovated Rajiv Smruthi Bhavan, the complex provides glass-floor views, interactive digital touchscreens, and audio-visual archives detailing Indian naval aviation history.',
 4, 'Beach Road, Kirlampudi Layout, Visakhapatnam, Andhra Pradesh 530017',
 17.7169000, 83.3308000, 'October to March', '2:00 PM - 8:30 PM (Sundays: 10:00 AM - 8:30 PM; Closed Mondays)', 'INR 50 adults, INR 30 children',
 'Visit all three RK Beach museums together in an afternoon naval heritage circuit.',
 'Observe the vertical take-off Harrier jet suspended mid-air, explore naval combat artifacts, watch short documentary films.',
 'https://images.unsplash.com/photo-1517976487507-5b3b4b45f942?auto=format&fit=crop&w=1200&q=80',
 FALSE, TRUE),

(9, 'Indira Gandhi Zoological Park', 'indira-gandhi-zoological-park',
 'One of the largest wildlife sanctuaries in India, spanning 625 acres amidst Kambalakonda reserve forest.',
 'Surrounded by the scenic Eastern Ghats on three sides and the Bay of Bengal on the fourth, this expansive zoological park is home to over 80 species of animals, primates, and migratory birds. Highlights include Asiatic lions, Royal Bengal tigers, white tigers, Indian rhinoceroses, and a tranquil natural lake sanctuary attracting seasonal pelicans and storks.',
 7, 'Near Dairy Farm, Yendada, Visakhapatnam, Andhra Pradesh 530040',
 17.7686000, 83.3468000, 'October to February', '9:00 AM - 5:00 PM (Closed Mondays)', 'INR 50 adults, INR 10 children (Battery vehicles available)',
 'Rent battery-operated eco-vehicles or bicycles at the main gate to explore the massive 625-acre park comfortably.',
 'Spot white tigers and Asian elephants, take a battery buggy ride, observe rare waterfowl around the lake.',
 'https://images.unsplash.com/photo-1534188753412-3e26d0d618d6?auto=format&fit=crop&w=1200&q=80',
 TRUE, TRUE),

(10, 'Tenneti Park', 'tenneti-park',
 'A breathtaking seaside cliff park overlooking the turquoise bay and dramatic natural rocks.',
 'Located along the scenic Bheemili Beach Road, Tenneti Park is perched gracefully on coastal cliffs. Lush greenery, paved hillside walkways, and shaded sea-facing gazebos provide front-row seats to crashing ocean waves. In recent years, it gained immense popularity with visitors drawn to view the grounded Bangladesh cargo vessel MV Maa near the rocky shoreline.',
 7, 'Beach Road, Jodugullapalem, Visakhapatnam, Andhra Pradesh 530040',
 17.7592000, 83.3533000, 'September to March', '6:00 AM - 9:00 PM daily', 'INR 10 per person',
 'A prime photography location for sunrises. Paved staircases lead all the way down to the rock beach.',
 'Relax in sea-facing gazebos, photograph waves breaking on rocky outcrops, watch the coastal sunrise, walk down to the beach.',
 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=1200&q=80',
 TRUE, TRUE),

(11, 'Dolphin’s Nose & Blackmores Hill Lighthouse', 'dolphins-nose',
 'A prominent 358-meter rocky headland resembling a dolphin snout with a historic ocean lighthouse.',
 'Rising dramatically into the Bay of Bengal at an altitude of 358 meters above sea level, Dolphin Nose is a giant rocky promontory that shelters Visakhapatnam natural harbor from severe oceanic storms. At its summit stands the historic Blackmores Hill Lighthouse, whose powerful optical beacon projects light 64 kilometers across international maritime shipping lanes.',
 2, 'Dolphin Nose Hill, Gangavaram Port Road, Visakhapatnam, Andhra Pradesh 530005',
 17.6749000, 83.2941000, 'October to March', '3:00 PM - 5:00 PM (Lighthouse visiting hours)', 'INR 10 for lighthouse entry',
 'Lighthouse observation deck has narrow spiral stairs and limited visiting hours; arrive by 3:30 PM.',
 'Enjoy the 360-degree vista of Vizag port, see international cargo ships, photograph the unique headland formation.',
 'https://images.unsplash.com/photo-1518457607834-6e8d80c183c5?auto=format&fit=crop&w=1200&q=80',
 TRUE, TRUE),

(12, 'Borra Caves (Ananthagiri)', 'borra-caves',
 'Million-year-old million-ton speleothem caves carved deep into the limestone of Ananthagiri hills.',
 'Discovered by British geologist William King in 1807, Borra Caves are among the largest and deepest cave systems in India, situated at an elevation of 705 meters in the Ananthagiri hill range. The Gosthani River flows subterranean through the karst formation, shaping extraordinary million-year-old stalactites and stalagmites that AP Tourism has illuminated with stunning multi-color lighting.',
 6, 'Ananthagiri Mandal, Alluri Sitharama Raju District, Andhra Pradesh 535145',
 18.2809000, 83.0396000, 'October to March', '10:00 AM - 5:00 PM (Lunch break: 1:00 PM - 2:00 PM)', 'INR 80 adults, INR 60 children, INR 100 camera',
 'The cave floor can be damp and slippery; wear shoes with good grip. The scenic Vistadome train stops at Borra Caves railway station.',
 'Wander through subterranean limestone chambers, spot stalagmite formations resembling Lord Shiva and Kamadhenu, taste fresh bamboo chicken outside.',
 'https://images.unsplash.com/photo-1509316975850-ff9c5deb0cd9?auto=format&fit=crop&w=1200&q=80',
 TRUE, TRUE),

(13, 'Araku Valley Tribal Museum', 'araku-tribal-museum',
 'An authentic window into the lifestyle, art, customs, and rich heritage of indigenous Eastern Ghats tribes.',
 'Established by the Andhra Pradesh Tourism Development Corporation, the Tribal Museum in Araku Valley celebrates the vibrant cultures of indigenous tribal groups such as the Valmiki, Bagata, Khond, and Porja. Constructed with eco-friendly mud, bamboo, and thatch, the museum displays authentic tribal artifacts, hunting equipment, clay dioramas depicting Dhimsa dance, and handicraft stalls.',
 4, 'Araku Valley, Alluri Sitharama Raju District, Andhra Pradesh 531149',
 18.3333000, 82.8833000, 'September to February', '10:00 AM - 7:00 PM', 'INR 40 adults, INR 20 children',
 'Try the on-site archery range and buy certified Araku Valley organic coffee, forest honey, and handmade tribal wooden crafts.',
 'Watch traditional Dhimsa tribal dance demonstrations, purchase authentic Araku organic coffee and spices, view historic tribal tools.',
 'https://images.unsplash.com/photo-1544644181-1484b3fdfc62?auto=format&fit=crop&w=1200&q=80',
 TRUE, TRUE),

(14, 'Katiki Waterfalls', 'katiki-waterfalls',
 'A majestic 50-foot forest waterfall cascading into lush pools of the Gosthani River basin.',
 'Named after the mythical village of Katiki, this pristine natural waterfall originates from the Gosthani River approximately 4 kilometers away from Borra Caves. Reached via a thrilling four-wheel drive jeep safari through bumpy forest terrain followed by a scenic 20-minute trek, Katiki rewards adventurers with cold natural pools surrounded by dense mountain greenery.',
 6, 'Near Borra Caves, Katiki Village, Andhra Pradesh 531149',
 18.2917000, 83.0117000, 'August to January (Post-monsoon)', '6:00 AM - 5:00 PM', 'Jeep ride approx INR 250 - 300 per head; Free waterfall entry',
 'Jeep ride on unpaved track is bumpy; hold on tight. Carry extra clothes and waterproof footwear.',
 'Trek through moist deciduous forests, dip in the natural mountain plunge pool, savor spicy local bamboo chicken cooked on coal.',
 'https://images.unsplash.com/photo-1432405972618-c60b0225b8f9?auto=format&fit=crop&w=1200&q=80',
 TRUE, TRUE),

(15, 'Chaparai Water Cascades', 'chaparai-waterfalls',
 'Gentle mountain stream gliding over massive smooth slanting rock formations in Araku.',
 'Located about 15 kilometers from Araku town, Chaparai (also called Dumbriguda Waterfalls) is a scenic tourist hotspot where clear mountain waters flow over broad, sloping rock sheets surrounded by thick pine and sal forests. The gentle flow over smooth granite rocks makes it a favorite natural water slide for families and picnickers.',
 6, 'Dumbriguda Mandal, Araku Valley, Andhra Pradesh 531151',
 18.3150000, 82.7690000, 'September to February', '8:00 AM - 6:00 PM', 'INR 10 entry fee',
 'Rocks can be slippery with algae during peak monsoon. Follow warning signs and stay in designated shallow zones.',
 'Slide along gently sloping natural water rocks, picnic under green forest canopy, sample sizzling bamboo mutton and herbal teas.',
 'https://images.unsplash.com/photo-1511556532299-8f662fc26c06?auto=format&fit=crop&w=1200&q=80',
 FALSE, TRUE),

(16, 'Thotlakonda Buddhist Complex', 'thotlakonda-buddhism',
 'A 2,000-year-old Hinayana Buddhist monastic settlement atop a scenic coastal hillock.',
 'Perched on a serene hill 128 meters above the Bay of Bengal, Thotlakonda is a significant Buddhist archaeological site excavated in 1988. Thriving between the 2nd century BCE and 2nd century CE, the complex includes grand stupas, chaityagrihas (prayer halls), viharas (monks residences), refectory stone dining tables, and large stone-cut rain harvesting cisterns overlooking the ocean.',
 3, 'Bheemunipatnam Mandal, Visakhapatnam District, Andhra Pradesh 530048',
 17.8286000, 83.4147000, 'October to March', '9:00 AM - 5:30 PM', 'INR 20 adults',
 'Exceptional photography spot for both ancient archaeology and ocean horizon. Carry sun protection as there is minimal shade.',
 'Walk among 2,000-year-old circular stupas, examine rock-hewn rainwater cisterns, absorb tranquil spiritual ambiance with sea views.',
 'https://images.unsplash.com/photo-1548013146-72479768bada?auto=format&fit=crop&w=1200&q=80',
 TRUE, TRUE),

(17, 'Bavikonda Buddhist Heritage Site', 'bavikonda-buddhism',
 'One of the oldest and sacred Buddhist excavation sites on the coastal hill range of Vizag.',
 'Bavikonda (meaning Hill of Wells in Telugu due to numerous rock-cut rainwater wells) is a prominent Hinayana Buddhist monastery dating back to the 3rd century BCE. Archaeologists uncovered a bone relic housed in an urn within the Mahastupa, widely believed to belong to the Buddha. The complex features pillared congregation halls, teaching quarters, and ancient brick pathways.',
 3, 'Near Timmapuram Village, Visakhapatnam, Andhra Pradesh 530048',
 17.8206000, 83.3875000, 'October to March', '9:00 AM - 5:00 PM', 'INR 15 per person',
 'Peaceful and less crowded than urban tourist spots. Great destination for history scholars and contemplative walks.',
 'Study early Buddhist architectural layout, inspect rock-cut water storage systems, enjoy panoramic coastal countryside views.',
 'https://images.unsplash.com/photo-1564507592333-c60657eea523?auto=format&fit=crop&w=1200&q=80',
 FALSE, TRUE),

(18, 'Bojjannakonda Rock-Cut Buddhist Monasteries', 'bojjannakonda-caves',
 'Ancient 4th-9th century CE rock-cut Buddhist monastery carved into two adjacent hillocks.',
 'Located near Anakapalle about 45 km from Vizag, Bojjannakonda and its twin hill Lingalakonda form one of the most remarkable Buddhist archaeological sites in South India. Carved out during the Theravada, Mahayana, and Vajrayana eras, the hillside features cave sanctuaries with carved Buddha reliefs, rock-hewn stupas, and monolithic multi-tiered monasteries.',
 3, 'Sankaram Village, Anakapalle, Andhra Pradesh 531002',
 17.7139000, 83.0161000, 'November to February', '9:00 AM - 5:00 PM', 'INR 25 per person (ASI maintained)',
 'Climb up the stone steps in early morning or late afternoon when stone temperatures are mild.',
 'Explore rock-cut monastic caves, photograph monolithic Buddha statues, discover ancient terracotta figures at the site museum.',
 'https://images.unsplash.com/photo-1548013146-72479768bada?auto=format&fit=crop&w=1200&q=80',
 FALSE, TRUE),

(19, 'Kondakarla Ava Bird Sanctuary & Freshwater Lake', 'kondakarla-ava',
 'Andhra Pradesh’s second largest natural freshwater lake and a haven for rare migratory bird species.',
 'Kondakarla Ava is a picturesque wetland fed by the Sarada River, surrounded by the foothills of Eastern Ghats. The lake is blanketed with thousands of pink lotus flowers and water lilies, creating a dreamlike landscape. Over 100 species of winged visitors, including pheasant-tailed jacanas, grey herons, egrets, and teals, nest here during winter.',
 7, 'Atchutapuram Mandal, Kondakarla Village, Andhra Pradesh 531033',
 17.5925000, 82.9972000, 'November to February (Migratory season)', '7:00 AM - 6:00 PM', 'INR 20 entry fee; Country boat ride INR 100 - 150',
 'Take an early morning boat ride on traditional catamarans made of tied palm logs for magical misty birdwatching.',
 'Glide through blooming pink lotus beds on local wooden raft boats, birdwatch with binoculars, photograph golden sunrise over the lake.',
 'https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=1200&q=80',
 TRUE, TRUE),

(20, 'Kambalakonda Wildlife Sanctuary', 'kambalakonda-wildlife',
 'A 70-square-kilometer dry evergreen forest reserve offering nature treks and canopy zipline adventures.',
 'Spanning 7,146 hectares of rugged hill terrain, Kambalakonda Wildlife Sanctuary preserves the fragile Eastern Ghats ecosystem right on the outskirts of Visakhapatnam. The sanctuary provides a secure habitat for leopards, Indian barking deer, wild boars, spotted chitals, jackals, and Russell vipers, featuring scenic hiking trails, an eco-tourism park, a butterfly meadow, and an adventure zipline.',
 7, 'NH16, Opposite Zoo Park, Visakhapatnam, Andhra Pradesh 530048',
 17.7889000, 83.3389000, 'October to March', '9:00 AM - 4:30 PM', 'INR 30 adults, INR 10 children',
 'Guided jungle treks are available in morning slots. Carry water, mosquito repellent, and binoculars.',
 'Trek through marked jungle trails, cross the rope suspension bridge, spot spotted deer near water reservoirs, go ziplining.',
 'https://images.unsplash.com/photo-1448375240586-882707db888b?auto=format&fit=crop&w=1200&q=80',
 TRUE, TRUE),

(21, 'Bheemili Beach & Dutch Heritage Town', 'bheemili-beach',
 'A peaceful coastal town steeped in 17th-century Dutch colonial history with quiet beaches and old lighthouses.',
 'Bheemunipatnam (Bheemili) sits at the mouth of the Gosthani River and is the second oldest municipality in mainland India. Established by the Dutch East India Company in the 1600s, the town retains colonial charms with its 1868 lighthouse, Dutch cemetery featuring obelisk tombs, Roman Catholic church, and quiet golden beach with gentle water ideal for long leisurely walks.',
 1, 'Bheemunipatnam, Visakhapatnam District, Andhra Pradesh 531163',
 17.8895000, 83.4548000, 'October to March', 'Open 24 hours', 'Free entry',
 'The coastal drive from Vizag to Bheemili along the Marine Drive is one of the most scenic coastal highways in South India.',
 'Drive along Vizag-Bheemili beach road, visit the historic Dutch cemetery and obelisks, photograph the 150-year-old lighthouse, eat seaside seafood.',
 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=1200&q=80',
 TRUE, TRUE),

(22, 'VMRDA City Central Park', 'vmrda-city-central-park',
 'An expansive 22-acre urban garden oasis in the heart of the city featuring musical dancing fountains.',
 'Spread across 22 verdant acres in Dwaraka Nagar, City Central Park is a landscaped urban haven featuring rolling manicured lawns, seasonal flower beds, children play zones, an ornamental bonsai garden, and the third largest musical dancing fountain in India. The evening fountain show synchronizes bursts of colored water with classical and contemporary music.',
 7, 'Old Jail Road, Opposite Bus Station, Visakhapatnam, Andhra Pradesh 530020',
 17.7289000, 83.3089000, 'All year round (Evenings best)', '9:00 AM - 8:30 PM (Musical Fountain: 7:00 PM & 8:00 PM)', 'INR 20 adults, INR 10 children',
 'Evenings are cool and vibrant. Do not miss the 7:00 PM musical fountain show on weekends.',
 'Watch the spectacular musical dancing fountain, jog on rubberized walking tracks, relax among flower gardens, visit the bonsai enclosure.',
 'https://images.unsplash.com/photo-1585320806297-9794b3e4eeae?auto=format&fit=crop&w=1200&q=80',
 FALSE, TRUE),

(23, 'Visakha Museum (Dutch Bungalow)', 'visakha-museum',
 'Housed in a 150-year-old Dutch bungalow, narrating the maritime and regional history of Kalingandhra.',
 'Situated on Beach Road inside a heritage Dutch-era summer bungalow constructed in the 1800s, the Visakha Museum showcases the cultural legacy of Visakhapatnam. Highlights include ancient bronze sculptures, 250-pounder unexploded naval shells from World War II, model ships, armor suits, royal relics of the Jeypore Maharajas, and historic photographs documenting Vizag transformation into a port city.',
 4, 'Beach Road, Opp. Palm Beach Hotel, Visakhapatnam, Andhra Pradesh 530017',
 17.7208000, 83.3350000, 'Year-round', '11:00 AM - 7:00 PM (Closed Fridays)', 'INR 20 adults, INR 10 children',
 'Guided tours help appreciate regional history. Photography is permitted in select galleries.',
 'See WWII naval ammunition shells, inspect royal ivory palanquins, study antique maritime cartography and Dutch coins.',
 'https://images.unsplash.com/photo-1566127444979-b3d2b654e3d7?auto=format&fit=crop&w=1200&q=80',
 FALSE, TRUE),

(24, 'Ross Hill Church', 'ross-hill-church',
 'A century-old Catholic chapel atop Ross Hill forming one of Vizag’s unique multi-faith religious peaks.',
 'Ross Hill is one of three hills lining Visakhapatnam harbor entrance, each crowned by places of worship of different faiths—a church, a mosque, and a Hindu temple—standing in complete communal harmony. The Roman Catholic Church of Our Lady of the Sacred Heart was built in 1877 and offers spellbinding views of container ships navigating into the port channels.',
 5, 'Port Area, Ross Hill, Visakhapatnam, Andhra Pradesh 530001',
 17.6917000, 83.2972000, 'All year round', '6:00 AM - 6:00 PM', 'Free entry',
 'Visit in late afternoon to watch shipping vessels entering the inner harbor against the golden hour sky.',
 'Attend quiet prayer services, view harbor channel operations from above, witness the multi-faith trinity hills of Vizag.',
 'https://images.unsplash.com/photo-1548625361-196022c366ff?auto=format&fit=crop&w=1200&q=80',
 FALSE, TRUE),

(25, 'Sri Kanaka Mahalakshmi Temple', 'kanaka-mahalakshmi-temple',
 'The beloved protector deity of Visakhapatnam located in the vibrant old town of Burujupeta.',
 'Sri Kanaka Mahalakshmi is revered as the guardian goddess of Visakhapatnam. Unlike traditional temples with high roof sanctums, the deity idol stands under the open sky without a roof, following an ancient legend that the Goddess desires natural rain and sunshine. Millions of devotees visit during the sacred Margasira month to seek prosperity and fulfillment.',
 5, 'Burujupeta, Old Town, Visakhapatnam, Andhra Pradesh 530001',
